"""
app.py -- YAKOL BI: Dashboard Financiero Ejecutivo
--------------------------------------------------------------------------------
Interfaz premium con 3 apartados: Dashboard Financiero, Resultados y
Recomendaciones, Exportacion a Excel. El flujo de entrada (ZIP, Excel
anterior, Training Allowance, costos) es EXACTAMENTE el mismo de siempre.

Regla de oro sin cambios: los montos de bono del promotor (Resumen_Bonos)
SIEMPRE vienen tal cual del PDF oficial -- nunca se recalculan. Esta capa
solo VISUALIZA lo que los modulos analiticos ya calcularon.
"""

import tempfile
from pathlib import Path

import pandas as pd
import streamlit as st

from ingesta import ingestar_zip, detectar_periodo_de_nombre
from clasificador import clasificar_lote
from extractores import EXTRACTORES, extraer_bonos_promotores
from transformacion import (
    construir_dim_periodo, construir_dim_asesor, construir_dim_promotor,
    construir_fact_igc, construir_fact_limra, construir_historico_actividad,
    construir_resumen_bonos, construir_historico_gmm, construir_historico_traspasos,
    fusionar_periodo, fusionar_dim_asesor,
)
from validaciones import validar_todo
from log_procesamiento import RegistroLog, construir_log
from excel_maestro import generar_excel_maestro, cargar_excel_maestro_existente
from analitica_cumplimiento import (
    calcular_comparativo_incumplimientos, calcular_seguimiento_igc, calcular_seguimiento_limra,
    calcular_seguimiento_bonos,
)
from analitica_avanzada import (
    calcular_segmentacion_asesores, detectar_anomalias, calcular_costeo_asesores,
    calcular_roi_campanas, calcular_real_vs_plan, calcular_analisis_sensibilidad,
    calcular_escenarios_montecarlo, calcular_tendencia_proyeccion,
)
from reglas_cuaderno import generar_explicacion_bonos, generar_estimacion_bono_siguiente_periodo
from hallazgos import (
    generar_hallazgos, calcular_semaforo_general, clasificar_asesores_en_riesgo,
    generar_plan_mitigacion_riesgo, identificar_asesores_destacados, identificar_menciones_especiales,
)
from graficas import (
    grafica_tendencia_igc_limra, grafica_bono_total_mensual, grafica_composicion_bonos,
    grafica_segmentacion, grafica_real_vs_plan, grafica_flujo_simplificado, gauge_semaforo,
    grafica_destacados_dispersion, interpretacion_destacados_dispersion,
    interpretacion_tendencia_igc_limra, interpretacion_bono_total_mensual,
    interpretacion_composicion_bonos, interpretacion_segmentacion,
    interpretacion_real_vs_plan, interpretacion_flujo,
)
from config_visual import CSS_CORPORATIVO, COLOR_PRIMARIO
from config import (
    TIPOS_REPORTE_ESPERADOS, SUELDO_SHARON_DEFAULT, PCT_SHARON_RECLUTAMIENTO_DEFAULT,
    CANALES_RECLUTAMIENTO, UMBRAL_LIMRA, UMBRAL_IGC,
)

LOGO_B64 = ""

NOMBRES_HOJAS_HISTORICAS = [
    "Resumen_Bonos", "Historico_Actividad", "Historico_GMM", "Historico_Traspasos",
    "Dim_Asesor", "Dim_Promotor", "Dim_Periodo", "Fact_IGC", "Fact_LIMRA", "Log_Procesamiento",
]

st.set_page_config(page_title="YAKOL BI -- Dashboard Financiero", page_icon=None, layout="wide")
st.markdown(CSS_CORPORATIVO, unsafe_allow_html=True)

st.markdown(f"""
<div class="yakol-topbar">
    <img src="data:image/png;base64,{LOGO_B64}">
    <div>
        <h1>YAKOL BI -- Dashboard Financiero Ejecutivo</h1>
        <p>Analisis financiero y estadistico automatizado para Yakol Consultoria Financiera</p>
    </div>
</div>
""", unsafe_allow_html=True)

# =============================================================================
# BLOQUE DE CARGA -- identico al de siempre
# =============================================================================

with st.container():
    st.markdown('<div class="seccion-titulo">1. Cargar informacion del mes</div>', unsafe_allow_html=True)
    col1, col2 = st.columns(2)
    with col1:
        archivo_zip = st.file_uploader("ZIP del mes", type=["zip"])
    with col2:
        excel_anterior = st.file_uploader("Excel Maestro anterior (opcional)", type=["xlsx"])

    periodo_manual = None
    if archivo_zip is not None and detectar_periodo_de_nombre(archivo_zip.name) is None:
        st.warning("No se pudo identificar el mes por el nombre del archivo. Confirmalo manualmente:")
        meses = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio",
                  "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"]
        c1, c2 = st.columns(2)
        with c1:
            mes_sel = st.selectbox("Mes", meses)
        with c2:
            anio_sel = st.number_input("Anio", min_value=2020, max_value=2035, value=2026, step=1)
        periodo_manual = f"{anio_sel}{meses.index(mes_sel) + 1:02d}"

    st.markdown('<div class="seccion-titulo">2. Variables que no vienen en ningun PDF</div>', unsafe_allow_html=True)
    with st.expander("Cuaderno de Concursos -- datos manuales", expanded=False):
        ganadores_training_allowance = st.number_input(
            "Numero de asesores ganadores de Training Allowance (ultimos 6 meses)",
            min_value=0, max_value=50, value=0, step=1,
        )
        training_allowance_capturado = st.checkbox("Ya confirme este dato con el director")
        otros_ingresos = st.number_input(
            "Otros ingresos del mes, independientes de los bonos ($)",
            min_value=0.0, value=0.0, step=500.0,
            help="Cualquier ingreso de la promotoria que no venga del Reporte de Bonos Promotores "
                 "(ej. comisiones adicionales, ingresos no ligados a bonos). Se suma automaticamente "
                 "al Total de Ingresos en el Dashboard Financiero.",
        )

    st.markdown('<div class="seccion-titulo">3. Costos del mes</div>', unsafe_allow_html=True)
    with st.expander("Sharon (reclutamiento)", expanded=False):
        st.caption(
            "Los costos fijos de la promotoria ya NO se capturan aqui -- se calculan "
            "automaticamente a partir del presupuesto real de 35 conceptos, prorrateado "
            "segun el numero de funciones de la promotoria."
        )
        c1, c2 = st.columns(2)
        with c1:
            sueldo_sharon = st.number_input("Sueldo mensual de Sharon ($)", min_value=0.0, value=SUELDO_SHARON_DEFAULT, step=500.0)
        with c2:
            pct_sharon = st.number_input("% dedicado a reclutamiento", min_value=0.0, max_value=100.0, value=PCT_SHARON_RECLUTAMIENTO_DEFAULT, step=5.0)
    with st.expander("Gasto por canal de reclutamiento este mes", expanded=False):
        gastos_canales = {}
        cols = st.columns(3)
        for i, canal in enumerate(CANALES_RECLUTAMIENTO):
            with cols[i % 3]:
                gastos_canales[canal] = st.number_input(canal, min_value=0.0, value=0.0, step=100.0, key=f"canal_{i}")
    with st.expander("Campana interna de Yakol este mes (deja en 0 si no hubo)", expanded=False):
        costo_campana_interna = st.number_input("Costo de la campana interna ($)", min_value=0.0, value=0.0, step=500.0)

    procesar = st.button("Procesar informacion", type="primary", disabled=archivo_zip is None)

# =============================================================================
# PROCESAMIENTO -- identico al de siempre
# =============================================================================

if procesar and archivo_zip is not None:
    with st.spinner("Procesando..."):
        carpeta_temp = tempfile.mkdtemp()
        ruta_zip_temp = Path(carpeta_temp) / archivo_zip.name
        with open(ruta_zip_temp, "wb") as f:
            f.write(archivo_zip.getbuffer())

        ingesta = ingestar_zip(str(ruta_zip_temp), carpeta_temp, id_periodo_manual=periodo_manual)
        for e in ingesta.errores:
            st.error(e)
        if ingesta.id_periodo is None:
            st.error("No se pudo determinar el periodo. Procesamiento detenido.")
            st.stop()
        id_periodo = ingesta.id_periodo

        clasificacion = clasificar_lote(ingesta.pdfs_encontrados)
        tipos_encontrados = {r.tipo for r in clasificacion if r.reconocido}
        tipos_faltantes = [t for t in TIPOS_REPORTE_ESPERADOS if t not in tipos_encontrados]
        no_reconocidos = [r.ruta_pdf for r in clasificacion if not r.reconocido]

        tablas_extraidas = {}
        datos_bonos_promotor = None
        for resultado in clasificacion:
            if not resultado.reconocido:
                continue
            if resultado.tipo == "BonosPromotores":
                datos_bonos_promotor = extraer_bonos_promotores(resultado.ruta_pdf)
                continue
            if resultado.tipo == "ConexionDesarrollo":
                continue
            funcion = EXTRACTORES.get(resultado.tipo)
            if funcion:
                tablas_extraidas[resultado.tipo] = funcion(resultado.ruta_pdf)

        if datos_bonos_promotor is None:
            st.error("No se encontro 'Reporte de Bonos Promotores' -- es la fuente oficial obligatoria. Detenido.")
            st.stop()
        if not datos_bonos_promotor["Bono_Total_Es_Oficial"]:
            st.warning("No se pudo extraer con certeza el resumen oficial de bonos del PDF. Revisa Resumen_Bonos manualmente.")

        dim_periodo_nuevo = construir_dim_periodo(id_periodo)
        dim_asesor_nuevo = construir_dim_asesor(tablas_extraidas.get("IGC"), tablas_extraidas.get("LIMRA"), tablas_extraidas.get("GMM"))
        dim_promotor_nuevo = construir_dim_promotor(datos_bonos_promotor["ID_Promotor"], datos_bonos_promotor["Nombre_Promotor"])
        fact_igc_nuevo = construir_fact_igc(tablas_extraidas.get("IGC"), id_periodo)
        fact_limra_nuevo = construir_fact_limra(tablas_extraidas.get("LIMRA"), id_periodo)
        hist_actividad_nuevo = construir_historico_actividad(tablas_extraidas.get("Actividad"), id_periodo)
        hist_gmm_nuevo = construir_historico_gmm(tablas_extraidas.get("GMM"), id_periodo)
        hist_traspasos_nuevo = construir_historico_traspasos(tablas_extraidas.get("Traspasos"), id_periodo)
        resumen_bonos_nuevo = construir_resumen_bonos(datos_bonos_promotor, id_periodo)

        historico = cargar_excel_maestro_existente(excel_anterior, NOMBRES_HOJAS_HISTORICAS)
        dim_asesor = fusionar_dim_asesor(historico.get("Dim_Asesor"), dim_asesor_nuevo)
        if historico.get("Dim_Promotor") is not None and not historico["Dim_Promotor"].empty:
            dim_promotor = pd.concat([historico["Dim_Promotor"], dim_promotor_nuevo], ignore_index=True).drop_duplicates(subset=["ID_Promotor"], keep="last")
        else:
            dim_promotor = dim_promotor_nuevo
        dim_periodo = fusionar_periodo(historico.get("Dim_Periodo"), dim_periodo_nuevo, id_periodo)
        fact_igc = fusionar_periodo(historico.get("Fact_IGC"), fact_igc_nuevo, id_periodo)
        fact_limra = fusionar_periodo(historico.get("Fact_LIMRA"), fact_limra_nuevo, id_periodo)
        hist_actividad = fusionar_periodo(historico.get("Historico_Actividad"), hist_actividad_nuevo, id_periodo)
        hist_gmm = fusionar_periodo(historico.get("Historico_GMM"), hist_gmm_nuevo, id_periodo)
        hist_traspasos = fusionar_periodo(historico.get("Historico_Traspasos"), hist_traspasos_nuevo, id_periodo)
        resumen_bonos = fusionar_periodo(historico.get("Resumen_Bonos"), resumen_bonos_nuevo, id_periodo)

        conteo_esperado = tablas_extraidas["IGC"]["ID_Asesor"].nunique() if tablas_extraidas.get("IGC") is not None else None
        resultado_validacion = validar_todo(resumen_bonos, hist_actividad, fact_igc, fact_limra, id_periodo, conteo_esperado)

        registro = RegistroLog(
            nombre_zip=archivo_zip.name, id_periodo=id_periodo, pdfs_encontrados=ingesta.conteo_encontrado,
            tipos_encontrados=sorted(tipos_encontrados), tipos_faltantes=tipos_faltantes,
            registros_importados=len(hist_actividad_nuevo) + 1,
            advertencias=resultado_validacion.advertencias, errores=resultado_validacion.errores,
        )
        log = construir_log(registro, historico.get("Log_Procesamiento"))

        if not resultado_validacion.valido:
            st.error("Errores que impiden generar un Excel Maestro confiable:")
            for e in resultado_validacion.errores:
                st.write(f"- {e}")
            st.stop()

        comparativo = calcular_comparativo_incumplimientos(fact_igc, fact_limra, dim_asesor)
        seguimiento_igc = calcular_seguimiento_igc(fact_igc)
        seguimiento_limra = calcular_seguimiento_limra(fact_limra)
        seguimiento_bonos = calcular_seguimiento_bonos(resumen_bonos)
        segmentacion = calcular_segmentacion_asesores(comparativo, hist_gmm, hist_actividad)
        alertas_anomalias = detectar_anomalias(hist_traspasos, hist_gmm)
        costeo_asesores = calcular_costeo_asesores(dim_asesor, id_periodo, sueldo_sharon, pct_sharon, gastos_canales, resumen_bonos)
        roi_campanas = calcular_roi_campanas(resumen_bonos, id_periodo, costo_campana_interna)
        real_vs_plan = calcular_real_vs_plan(hist_actividad, dim_asesor, id_periodo)
        sensibilidad = calcular_analisis_sensibilidad(resumen_bonos, id_periodo)
        escenarios_montecarlo = calcular_escenarios_montecarlo(resumen_bonos)
        tendencia = calcular_tendencia_proyeccion(resumen_bonos)
        destacados = identificar_asesores_destacados(segmentacion, comparativo, hist_actividad)
        menciones_especiales = identificar_menciones_especiales(segmentacion, comparativo)

        ganadores_ta = ganadores_training_allowance if training_allowance_capturado else None
        explicacion_bonos = generar_explicacion_bonos(resumen_bonos, hist_gmm, dim_asesor, ganadores_ta)
        estimacion_siguiente = generar_estimacion_bono_siguiente_periodo(resumen_bonos, hist_gmm, dim_promotor, ganadores_ta)

        ruta_salida = Path(carpeta_temp) / f"Excel_Maestro_YAKOL_{id_periodo}.xlsx"
        generar_excel_maestro({
            "Resumen_Bonos": resumen_bonos, "Explicacion_Bonos": explicacion_bonos,
            "Estimacion_Bonos_Siguiente": estimacion_siguiente, "Seguimiento_Bonos": seguimiento_bonos,
            "Real_vs_Plan": real_vs_plan, "Costeo_Asesores": costeo_asesores, "ROI_Campanas": roi_campanas,
            "Comparativo_Incumplimientos": comparativo, "Seguimiento_IGC": seguimiento_igc,
            "Seguimiento_LIMRA": seguimiento_limra, "Segmentacion_Asesores": segmentacion,
            "Asesores_Destacados": destacados,
            "Alertas_Anomalias": alertas_anomalias, "Escenarios_MonteCarlo": escenarios_montecarlo,
            "Tendencia_Proyeccion": tendencia, "Analisis_Sensibilidad": sensibilidad,
            "Historico_Actividad": hist_actividad, "Historico_GMM": hist_gmm,
            "Historico_Traspasos": hist_traspasos, "Dim_Asesor": dim_asesor, "Dim_Promotor": dim_promotor,
            "Dim_Periodo": dim_periodo, "Fact_IGC": fact_igc, "Fact_LIMRA": fact_limra, "Log_Procesamiento": log,
        }, str(ruta_salida))

        # Guardamos todo en session_state para que las 3 pestanas lo compartan
        st.session_state["datos"] = dict(
            id_periodo=id_periodo, resumen_bonos=resumen_bonos, comparativo=comparativo,
            segmentacion=segmentacion, alertas_anomalias=alertas_anomalias, real_vs_plan=real_vs_plan,
            costeo_asesores=costeo_asesores, roi_campanas=roi_campanas, hist_traspasos=hist_traspasos,
            destacados=destacados, menciones_especiales=menciones_especiales,
            explicacion_bonos=explicacion_bonos, estimacion_siguiente=estimacion_siguiente,
            escenarios_montecarlo=escenarios_montecarlo, tendencia=tendencia, sensibilidad=sensibilidad,
            ruta_excel=str(ruta_salida), tipos_faltantes=tipos_faltantes, no_reconocidos=no_reconocidos,
            advertencias=resultado_validacion.advertencias,
        )
    st.success(f"Informacion procesada correctamente para el periodo {id_periodo}. Revisa las pestanas de abajo.")

# =============================================================================
# LAS 3 PESTANAS
# =============================================================================

if "datos" in st.session_state:
    d = st.session_state["datos"]

    tab1, tab2, tab3 = st.tabs(["Dashboard Financiero", "Resultados y Recomendaciones", "Exportacion a Excel"])

    # -------------------------------------------------------------------
    # TAB 1 -- DASHBOARD FINANCIERO
    # -------------------------------------------------------------------
    with tab1:
        nivel, etiqueta = calcular_semaforo_general(d["comparativo"], d["resumen_bonos"])
        st.markdown(f'<span class="semaforo-badge semaforo-{nivel}">Estado General: {etiqueta}</span>', unsafe_allow_html=True)
        st.write("")

        rb = d["resumen_bonos"].sort_values("ID_Periodo") if d["resumen_bonos"] is not None and not d["resumen_bonos"].empty else None
        ultimo = rb.iloc[-1] if rb is not None else None
        anterior = rb.iloc[-2] if rb is not None and len(rb) >= 2 else None

        # LIMRA aparece primero/a la izquierda, con una diferencia visual
        # sutil respecto a IGC (borde ligeramente mas grueso) -- ambos
        # indicadores son igual de importantes, solo se le da una prioridad
        # de lectura leve a LIMRA, tal como pidio el director.
        igc_val = ultimo["IGC"] if ultimo is not None else 0
        limra_val = ultimo["LIMRA"] if ultimo is not None else 0

        st.caption(
            f"**Valores minimos oficiales de referencia:** LIMRA {UMBRAL_LIMRA:.2f}% &nbsp;|&nbsp; "
            f"IGC {UMBRAL_IGC:.2f}% -- utilizados en todas las evaluaciones, alertas y clasificaciones "
            f"de este Dashboard."
        )

        col1, col2, col3, col4 = st.columns(4)
        with col1:
            clase = "exito" if limra_val >= 86.00 else "peligro"
            st.markdown(f'''<div class="kpi-card {clase}" style="border-left-width:5px;">
                        <div class="kpi-label">LIMRA del Promotor</div>
                        <div class="kpi-value">{limra_val:.2f}%</div></div>''', unsafe_allow_html=True)
        with col2:
            clase = "exito" if igc_val >= 90.25 else "peligro"
            st.markdown(f'''<div class="kpi-card {clase}"><div class="kpi-label">IGC del Promotor</div>
                        <div class="kpi-value">{igc_val:.2f}%</div></div>''', unsafe_allow_html=True)
        with col3:
            bono_val = ultimo["Bono_Total"] if ultimo is not None else 0
            clase = "exito" if bono_val > 0 else "advertencia"
            st.markdown(f'''<div class="kpi-card {clase}"><div class="kpi-label">Bono Total del Mes</div>
                        <div class="kpi-value">${bono_val:,.0f}</div></div>''', unsafe_allow_html=True)
        with col4:
            n_riesgo = 0
            if d["comparativo"] is not None and not d["comparativo"].empty:
                sub = d["comparativo"][d["comparativo"]["ID_Periodo"] == d["comparativo"]["ID_Periodo"].max()]
                n_riesgo = ((sub["Incumple_Real_IGC"] .isin([True, "VERDADERO"])) | (sub["Incumple_Real_LIMRA"] .isin([True, "VERDADERO"]))).sum()
            clase = "peligro" if n_riesgo > 0 else "exito"
            st.markdown(f'''<div class="kpi-card {clase}"><div class="kpi-label">Asesores en Riesgo</div>
                        <div class="kpi-value">{n_riesgo}</div></div>''', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Tendencia de Cumplimiento y Bonos</div>', unsafe_allow_html=True)
        colA, colB = st.columns(2)
        with colA:
            st.plotly_chart(grafica_tendencia_igc_limra(d["resumen_bonos"]), use_container_width=True)
        with colB:
            st.plotly_chart(grafica_bono_total_mensual(d["resumen_bonos"]), use_container_width=True)
        st.markdown(
            f'<div class="interpretacion-box"><b>INTERPRETACION DEL RESULTADO</b><br>'
            f'{interpretacion_tendencia_igc_limra(d["resumen_bonos"])} '
            f'{interpretacion_bono_total_mensual(d["resumen_bonos"])}'
            f'</div>', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Semaforos de Cumplimiento Normativo</div>', unsafe_allow_html=True)
        colG1, colG2 = st.columns(2)
        with colG1:
            st.plotly_chart(gauge_semaforo(limra_val, "LIMRA del Promotor (minimo 86.00%)", 86.00, 90, invertido=False),
                             use_container_width=True)
        with colG2:
            st.plotly_chart(gauge_semaforo(igc_val, "IGC del Promotor (minimo 90.25%)", 90.25, 94, invertido=False),
                             use_container_width=True)

        st.markdown('<div class="seccion-titulo">Comparativo de Ingresos, Egresos y Flujo Neto del Mes</div>', unsafe_allow_html=True)
        fig_flujo, ingresos_totales, egresos_totales, flujo_neto = grafica_flujo_simplificado(
            d["resumen_bonos"], d["costeo_asesores"], otros_ingresos)
        st.plotly_chart(fig_flujo, use_container_width=True)
        st.markdown(
            f'<div class="interpretacion-box"><b>INTERPRETACION DEL RESULTADO</b><br>'
            f'{interpretacion_flujo(d["resumen_bonos"], ingresos_totales, egresos_totales, flujo_neto, otros_ingresos)}'
            f'</div>', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Composicion del Bono y Segmentacion de Asesores</div>', unsafe_allow_html=True)
        colD, colE = st.columns(2)
        with colD:
            st.plotly_chart(grafica_composicion_bonos(d["resumen_bonos"]), use_container_width=True)
        with colE:
            st.plotly_chart(grafica_segmentacion(d["segmentacion"]), use_container_width=True)
        st.markdown(
            f'<div class="interpretacion-box"><b>INTERPRETACION DEL RESULTADO</b><br>'
            f'{interpretacion_composicion_bonos(d["resumen_bonos"])} '
            f'{interpretacion_segmentacion(d["segmentacion"])}'
            f'</div>', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Avance Real vs. Meta Anual</div>', unsafe_allow_html=True)
        st.plotly_chart(grafica_real_vs_plan(d["real_vs_plan"]), use_container_width=True)
        st.markdown(
            f'<div class="interpretacion-box"><b>INTERPRETACION DEL RESULTADO</b><br>'
            f'{interpretacion_real_vs_plan(d["real_vs_plan"])}'
            f'</div>', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Detalle de Asesores (buscable y ordenable)</div>', unsafe_allow_html=True)
        if d["comparativo"] is not None and not d["comparativo"].empty:
            busqueda = st.text_input("Buscar asesor por nombre")
            tabla = d["comparativo"][d["comparativo"]["ID_Periodo"] == d["comparativo"]["ID_Periodo"].max()].copy()
            if busqueda:
                tabla = tabla[tabla["Nombre_Asesor"].str.contains(busqueda, case=False, na=False)]
            tabla_mostrar = tabla[["ID_Asesor", "Nombre_Asesor", "LIMRA_Indice_Real", "IGC_Indice_Real",
                                     "Incumple_Real_LIMRA", "Incumple_Real_IGC"]].copy()
            tabla_mostrar["Incumple_Real_LIMRA"] = tabla_mostrar["Incumple_Real_LIMRA"].apply(
                lambda v: "No cumple" if v in (True, "VERDADERO") else "Cumple")
            tabla_mostrar["Incumple_Real_IGC"] = tabla_mostrar["Incumple_Real_IGC"].apply(
                lambda v: "No cumple" if v in (True, "VERDADERO") else "Cumple")
            tabla_mostrar.columns = ["Numero de Asesor", "Nombre del Asesor", "LIMRA (%)", "IGC (%)",
                                       "Estado LIMRA", "Estado IGC"]
            st.dataframe(
                tabla_mostrar, use_container_width=True, hide_index=True, height=440,
                column_config={
                    "Numero de Asesor": st.column_config.TextColumn(width="small"),
                    "Nombre del Asesor": st.column_config.TextColumn(width="medium"),
                    "LIMRA (%)": st.column_config.NumberColumn(format="%.2f%%", width="small"),
                    "IGC (%)": st.column_config.NumberColumn(format="%.2f%%", width="small"),
                    "Estado LIMRA": st.column_config.TextColumn(width="small"),
                    "Estado IGC": st.column_config.TextColumn(width="small"),
                },
            )

    # -------------------------------------------------------------------
    # TAB 2 -- RESULTADOS Y RECOMENDACIONES
    # -------------------------------------------------------------------
    with tab2:
        st.markdown('<div class="seccion-titulo">Hallazgos y Recomendaciones del Periodo</div>', unsafe_allow_html=True)
        hallazgos = generar_hallazgos(
            d["resumen_bonos"], d["comparativo"], d["segmentacion"], d["alertas_anomalias"],
            d["real_vs_plan"], d["costeo_asesores"], d["roi_campanas"], d["hist_traspasos"],
        )
        etiqueta_tipo = {"riesgo": ("Riesgo", "riesgo"), "oportunidad": ("Oportunidad", "oportunidad"),
                          "recomendacion": ("Recomendacion", "recomendacion")}
        for h in hallazgos:
            nombre, clase_css = etiqueta_tipo[h["tipo"]]
            st.markdown(f'''<div class="hallazgo-card {clase_css}">
                <div class="hallazgo-titulo">[{nombre} -- {h["modulo"]}] {h["titulo"]}</div>
                <div class="hallazgo-seccion"><b>HALLAZGO:</b> {h["hallazgo"]}</div>
                <div class="hallazgo-seccion"><b>EVIDENCIA:</b> {h["evidencia"]}</div>
                <div class="hallazgo-seccion"><b>IMPACTO:</b> {h["impacto"]}</div>
                <div class="hallazgo-seccion"><b>RECOMENDACION:</b> {h["recomendacion"]}</div>
                </div>''', unsafe_allow_html=True)

        # -----------------------------------------------------------------
        # ASESORES DESTACADOS -- contraparte de "Asesores en Riesgo", justo
        # antes de esa seccion (primero lo positivo, luego el riesgo).
        # -----------------------------------------------------------------
        st.markdown('<div class="seccion-titulo">Asesores Destacados -- Salud y Desempeno Sobresaliente</div>',
                    unsafe_allow_html=True)
        destacados, menciones = d["destacados"], d["menciones_especiales"]
        seg = d["segmentacion"]

        if seg is not None and not seg.empty and "Polizas_Vida" in seg.columns:
            promedio_general = seg.groupby("ID_Asesor")["Polizas_Vida"].mean().mean()
            if destacados is not None and not destacados.empty and pd.notna(promedio_general) and promedio_general > 0:
                ids_dest = set(destacados["ID_Asesor"])
                promedio_dest = seg[seg["ID_Asesor"].isin(ids_dest)].groupby("ID_Asesor")["Polizas_Vida"].mean().mean()
                if pd.notna(promedio_dest):
                    st.caption(
                        f"Como grupo, los asesores destacados producen en promedio {promedio_dest / promedio_general:.1f}x "
                        f"mas polizas de Vida por periodo que el promedio general de la fuerza de ventas evaluada "
                        f"({promedio_dest:.1f} vs. {promedio_general:.1f} polizas)."
                    )

        st.plotly_chart(grafica_destacados_dispersion(seg, destacados), use_container_width=True)
        st.markdown(f'<div class="interpretacion-box"><b>INTERPRETACION</b><br>'
                    f'{interpretacion_destacados_dispersion(destacados)}</div>', unsafe_allow_html=True)

        if menciones:
            cols_menciones = st.columns(len(menciones))
            for col, m in zip(cols_menciones, menciones):
                with col:
                    st.markdown(f'''<div class="hallazgo-card oportunidad">
                        <div class="hallazgo-titulo">{m["Titulo"]} -- {m["Nombre"]}</div>
                        <div class="hallazgo-seccion">{m["Explicacion"]}</div>
                        </div>''', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Asesores Destacados -- Detalle Individual</div>', unsafe_allow_html=True)
        if destacados is None or destacados.empty:
            st.info("Ningun asesor supera el umbral definido para calificar como destacado este periodo.")
        else:
            def _fmt_pct(v, decimales=0):
                return f"{v:.{decimales}f}%" if pd.notna(v) else "N/D"

            filas_html_destacados = "".join(
                f'''<div class="destacado-item">
                    <div class="destacado-item-titulo">#{int(row["Posicion"])} -- Asesor {row["ID_Asesor"]} -- {row["Nombre"]}
                        <span class="destacado-badge">{row["Titulo_Tematico"]}</span></div>
                    <div class="destacado-item-linea"><b>Indice de Desempeno Destacado:</b> {row["Indice_Desempeno_Destacado"]:.1f}
                        (Salud promedio {row["Promedio_Indice_Salud"]:.1f}, {row["Consistencia_Pct"]:.0f}% en banda alta)</div>
                    <div class="destacado-item-linea"><b>Antiguedad:</b> {int(row["Meses_Antiguedad"])} mes(es) &nbsp;|&nbsp;
                        <b>Mix de produccion (Vida):</b> {_fmt_pct(row["Pct_Mix_Vida"])} &nbsp;|&nbsp;
                        <b>Aporte a meta anual de Vida:</b> {_fmt_pct(row["Aporte_Meta_Anual_Polizas_Pct"], 1)}</div>
                    <div class="destacado-item-linea">{row["Explicacion"]}</div>
                    </div>'''
                for _, row in destacados.iterrows()
            )
            st.markdown(f'<div class="scroll-container">{filas_html_destacados}</div>', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Asesores en Riesgo -- Detalle Individual</div>', unsafe_allow_html=True)
        tabla_riesgo = clasificar_asesores_en_riesgo(d["comparativo"], d["segmentacion"])
        if tabla_riesgo.empty:
            st.success("Ningun asesor en incumplimiento real este periodo.")
        else:
            filas_html = "".join(
                f'''<div class="riesgo-item">
                    <div class="riesgo-item-titulo">Asesor {row["Numero de Asesor"]} -- {row["Nombre"]}
                        <span class="riesgo-badge {row["Nivel de Riesgo"].lower().replace(" ", "-")}">{row["Nivel de Riesgo"]}</span></div>
                    <div class="riesgo-item-linea"><b>Indicadores que influyeron:</b> {row["Indicadores que Influyeron"]}</div>
                    <div class="riesgo-item-linea"><b>Explicacion:</b> {row["Explicacion Especifica"]}</div>
                    </div>'''
                for _, row in tabla_riesgo.iterrows()
            )
            st.markdown(f'<div class="scroll-container">{filas_html}</div>', unsafe_allow_html=True)

        st.markdown('<div class="seccion-titulo">Analisis y Plan de Mitigacion del Riesgo por Asesor</div>', unsafe_allow_html=True)
        tabla_mitigacion = generar_plan_mitigacion_riesgo(d["comparativo"], d["segmentacion"])
        if tabla_mitigacion.empty:
            st.success("Ningun asesor requiere plan de mitigacion este periodo.")
        else:
            st.dataframe(tabla_mitigacion, use_container_width=True, hide_index=True, height=420)

        st.markdown('<div class="seccion-titulo">Proyeccion del Siguiente Periodo (segun el Cuaderno de Concursos)</div>', unsafe_allow_html=True)
        if d["estimacion_siguiente"] is not None and not d["estimacion_siguiente"].empty and "ID_Periodo_Proyectado" in d["estimacion_siguiente"].columns:
            est = d["estimacion_siguiente"].iloc[0]
            colX, colY = st.columns(2)
            with colX:
                st.info(f"**Bono Inicial:** {est['Bono_Inicial_Estado']}\n\n{est['Bono_Inicial_Diagnostico']}")
            with colY:
                st.info(f"**Bono Renovacion:** {est['Bono_Renovacion_Estado']}\n\n{est['Bono_Renovacion_Diagnostico']}")
        else:
            st.info("Se necesitan al menos 3 meses de historico para proyectar el siguiente periodo.")

    # -------------------------------------------------------------------
    # TAB 3 -- EXPORTACION A EXCEL
    # -------------------------------------------------------------------
    with tab3:
        st.markdown('<div class="seccion-titulo">Descargar Excel Maestro Completo</div>', unsafe_allow_html=True)
        st.write("Incluye las 24 hojas: bonos oficiales, cumplimiento, segmentacion, costeo, "
                 "escenarios, proyecciones y el historico completo acumulado.")
        if d["tipos_faltantes"]:
            st.warning(f"Reportes no encontrados en el ultimo ZIP procesado: {', '.join(d['tipos_faltantes'])}")
        if d["no_reconocidos"]:
            st.error(f"{len(d['no_reconocidos'])} archivo(s) no identificados en el ultimo ZIP.")
        if d["advertencias"]:
            with st.expander("Ver advertencias de la ultima corrida"):
                for a in d["advertencias"]:
                    st.write(f"- {a}")
        with open(d["ruta_excel"], "rb") as f:
            st.download_button("Descargar Excel Maestro", data=f.read(),
                                file_name=f"Excel_Maestro_YAKOL_{d['id_periodo']}.xlsx",
                                mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                                type="primary")
        st.caption("Guarda este archivo y subelo de nuevo el mes siguiente como 'Excel Maestro anterior'.")
